head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > setValue]<br/>SearchBox 컴포넌트의 실제 입력값을 설정합니다.",
    "validation" : [
        "value(필수) 파라미터로 화면에 표시되는 값이 아닌 실제 입력값을 설정합니다.",
        "displayFormat, editFormat 등 입력값의 포맷과 관련된 적용을 모두 제거한 실제 입력값을 설정합니다.",
        "setValue() 메소드 실행 시 입력값을 확정하는 과정이 진행되며, 이때 입력값에 대한 유효성 처리가 함께 수행됩니다.",
        "setValue() 메소드 실행 시 입력값이 마스크 문자의 갯수와 형식에 일치하지 않으면 정상적으로 입력되지 않습니다.",
        "setValue() 메소드로 입력값이 변경된 경우 onchange 이벤트는 발생하고, onviewchange 이벤트는 발생하지 않습니다.",
        "setValue() 메소드로 값 설정 후 Reset 버튼 표시 상태가 자동 갱신됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// SearchBox 의 실제 입력값(getValue) 확인
scwin.getValue = function (target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);
};



// SearchBox 의 화면 표시값(inner input.value) 확인
scwin.getText = function (target) {
    let inputElem = target.render.querySelector("input");
    let rtn = inputElem ? inputElem.value : '';
    wf_body_bottom.getObj("scwin").setReturnValue("text(display) : " + rtn);
};



// Reset 버튼 표시 상태 확인 (searchbox 는 값 있을 때 Reset 버튼 노출)
scwin.getResetBtnState = function (target) {
    let resetBtn = target.render.querySelector("[id*='___reset']");
    if (resetBtn) {
        let display = resetBtn.style.display;
        let visible = (display !== 'none') ? 'visible' : 'hidden';
        wf_body_bottom.getObj("scwin").setReturnValue("Reset DOM=O display='" + display + "' (" + visible + ")");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("Reset DOM=X");
    }
};



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("12AZaz0Z0zaZ");
    scwin.getResetBtnState(target1);
};

scwin.btn_getValue1_onclick = function (e) {
    scwin.getValue(target1);
};

scwin.btn_getText1_onclick = function (e) {
    scwin.getText(target1);
};



