// onchange 발생, onviewchange 미발생 확인용 핸들러
scwin.target_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target_onchange=====");
};

scwin.target_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target_onviewchange=====");
};



// 전체 setValue 호출
scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 11; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
};

// 전체 getValue 호출
scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 11; i ++)
        eval("scwin.btn_getValue"+i+"_onclick()");
};

// 전체 text(display) 확인
scwin.btn_getAllText_onclick = function (e) {
    for (var i = 1; i < 11; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};
